#!/usr/bin/env bash
# Extract the Siril source used as the stretch truth oracle, VERBATIM, from
# the Siril 1.4.0 release tarball. Nothing in siril/ is edited by hand: every
# file is either a whole upstream file or a run of whole upstream functions
# cut out by line number (signature line .. first following "}" at column 0).
#
#   SIRIL_SRC=/path/to/siril-1.4.0/src ./extract.sh
#
# The release tarball is https://free-astro.org/download/siril-1.4.0.tar.bz2
# (sha256 439def7c40ad783afb82e87f3c656d85b449c701f67ab0a9b97ca372ea2d73c9, the
# hash pinned by the Arch AUR PKGBUILD); SIRIL_SRC is its src/ directory once
# unpacked. Re-running this script
# must reproduce siril/ byte for byte (`make verify-excerpt` checks that).
set -euo pipefail

SIRIL_SRC=${SIRIL_SRC:?set SIRIL_SRC to the src/ directory of an unpacked Siril 1.4.0 tree}
OUT=$(cd "$(dirname "$0")" && pwd)/siril
mkdir -p "$OUT/filters" "$OUT/core" "$OUT/rt"

# fn FILE REGEX: print the function whose signature line matches REGEX, up to
# and including the first line that is exactly "}".
fn() {
	awk -v re="$2" '
		!on && $0 ~ re { on = 1; printf "/* ---- %s:%d ---- */\n", FILENAME, NR }
		on { print }
		on && $0 == "}" { exit }
	' "$SIRIL_SRC/$1" | sed "s#$SIRIL_SRC/##"
}

banner() {
	echo "/* VERBATIM excerpt of Siril 1.4.0 (GPL-3.0-or-later, (C) team free-astro)."
	echo " * Generated by stretch/testdata/sref/extract.sh -- do not edit. */"
}

# Whole files, unmodified.
cp "$SIRIL_SRC/filters/mtf.c" "$SIRIL_SRC/filters/mtf.h" "$OUT/filters/"
cp "$SIRIL_SRC/filters/ght.c" "$SIRIL_SRC/filters/ght.h" "$OUT/filters/"
cp "$SIRIL_SRC/core/arithm.h" "$OUT/core/"
cp "$SIRIL_SRC/rt/rt_math.h" "$OUT/rt/"

# asinh.c: the processing functions only (the rest of the file is GTK UI).
{
	banner
	echo '#include <math.h>'
	echo '#include "core/siril.h"'
	echo '#include "core/proto.h"'
	echo '#include "core/arithm.h"'
	echo '#include "algos/statistics.h"'
	sed -n '41p' "$SIRIL_SRC/filters/asinh.c"
	fn filters/asinh.c '^int asinhlut_ushort[(]'
	fn filters/asinh.c '^static int asinhlut_float[(]'
	fn filters/asinh.c '^int asinhlut[(]'
	fn filters/asinh.c '^int command_asinh[(]'
} > "$OUT/filters/asinh_excerpt.c"

# The statistics used by autostretch (median and MAD of the non-zero pixels).
{
	banner
	echo '#include "stats_excerpt_prelude.h"'
	fn algos/quantize.c '^static int FnMeanSigma_float[(]float [*]array, /[*]'
	fn algos/statistics_float.c '^static float[*] reassign_to_non_null_data_float[(]'
	fn algos/statistics_float.c '^double siril_stats_float_mad[(]'
	fn algos/sorting.c '^double histogram_median_float[(]'
} > "$OUT/stats_excerpt.c"

{
	banner
	echo '#include <algorithm>'
	echo '#include <cassert>'
	echo '#include <cmath>'
	echo '#include <cstdint>'
	echo '#include <vector>'
	echo '#include "rt/rt_math.h"'
	sed -n '162,165p' "$SIRIL_SRC/rt/rt_algo.cc"
	fn rt/rt_algo.cc '^void findMinMaxPercentile[(]'
	echo '} /* namespace rtengine (rt_algo.cc:162) */'
} > "$OUT/rt_algo_excerpt.cc"

# OpenCV CLAHE path used by the `clahe` command on 32-bit float images.
{
	banner
	echo '#include "opencv_excerpt_prelude.h"'
	fn opencv/opencv.cpp '^float [*]fits_to_bgrbgr_float[(]'
	fn opencv/opencv.cpp '^static int cvClahe_float[(]'
} > "$OUT/opencv_excerpt.cpp"

echo "extracted from $SIRIL_SRC into $OUT"
